-- 用于 DreamSpaceLvl2_Demo 单场景测试




---@class SingleLuaSceneManagerLorLvl2
local SingleLuaSceneManagerLorLvl2 = Class('SingleLuaSceneManagerLorLvl2')

-- ========================================================


local DreamlandUtils = import('Game.UI.FightReady.UIDreamland.DreamlandUtils')


--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程



local ETCJoystick = import('Game.Behaviours.ETCJoystick')
---@type LuaParametersReader
local LuaParametersReader = import('Game.Utils.LuaParametersReader')


---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Canvas = CS.UnityEngine.Canvas
local Physics = CS.UnityEngine.Physics
local Input = CS.UnityEngine.Input
local LayerMask = CS.UnityEngine.LayerMask
local QueryTriggerInteraction = CS.UnityEngine.QueryTriggerInteraction
local Physics              = CS.UnityEngine.Physics
local Application = CS.UnityEngine.Application
local ResourceModule = CS.Engine.Modules.ResourceModule


--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local Vector3 = CS.UnityEngine.Vector3

local DreamSpaceUtils = CS.DreamSpace.DreamSpaceUtils
local LuaParameters = CS.Engine.Modules.LuaParameters

local GlobalsInDreamSpace = CS.DreamSpace.GlobalsInDreamSpace


local Canvas = CS.UnityEngine.Canvas
local RenderMode = CS.UnityEngine.RenderMode

local URPCameraController = CS.Game.Native.URP.URPCameraController.Instance

local DreamSpaceLuaUtils = import('Game.DreamSpace.Tools.DreamSpaceLuaUtils')
---@type DreamSpaceStates
local DreamSpaceStates = import('Game.DreamSpace.Tools.DreamSpaceStates')
local KeyboardInfo = DreamSpaceStates.KeyboardInfo
local KeyboardInputMap = import("Game.DreamSpace.CharacterController.KeyboardInputMap")

local InspectHint = import('Game.DreamSpace.Hint.InspectHint')
local GearHint = import('Game.DreamSpace.Hint.GearHint')





-- ========================================================

local defaultLayer = LayerMask.NameToLayer( "Default" )
local roleLayer = LayerMask.NameToLayer( "role" )           -- "Human", "Cat" 所在层

-- ========================================================


function SingleLuaSceneManagerLorLvl2:__init()
    self.controller = nil
end


function SingleLuaSceneManagerLorLvl2:__delete()
    self.co = nil
end



function SingleLuaSceneManagerLorLvl2:Awake()
    KTool.SetActive(self.controller.gameObject, true);


    Application.targetFrameRate = 60.0


    -- 下面这部分要写在 Awake 里
    -- 若写到 Start 里, 可能会和 角色控制的某些设置代码冲突,..,  
    self.isLayerIgnore_Role_Default = Physics.GetIgnoreLayerCollision( roleLayer, defaultLayer )
    if self.isLayerIgnore_Role_Default == true then 
        print("设置----")
        Physics.IgnoreLayerCollision( roleLayer, defaultLayer, false ) -- 让两层相互参与碰撞
    end 
    print( "两层是否碰撞: role-default = " .. tostring(not Physics.GetIgnoreLayerCollision( roleLayer, defaultLayer )) )

    Physics.autoSimulation = true
    Input.multiTouchEnabled = true


    -- PC / Mobile 平台:
    DreamSpaceStates.CheckPlatform()
    
end



function SingleLuaSceneManagerLorLvl2:Start()
    KTool.SetActive(self.controller.gameObject, true)

    -- ===================
    self.EventStart  = Events.AddListener(DreamSpaceStates.EventNames.OnCreatePlayerInitEnd, function()
        --printError("-- start")
        self:RegisterInputFunc()
    end)


    self.EventDestroy  = Events.AddListener(DreamSpaceStates.EventNames.OnCreatePlayerDestroy, function()
        --printError("-- destroy")
        self:UnRegisterInputFunc()
    end)

    self:Test()

    self.co = cs_coroutine.start(self.DelayInit, self)
end


function SingleLuaSceneManagerLorLvl2:DelayInit()
    local RoleControllerLoader = import('Game.DreamSpace.CharacterController.RoleControllerLoader')

    -- -1-
    RoleControllerLoader.ResetAll() 

    -- -2- 
    RoleControllerLoader.RegistLoadPaths({
        "DreamSpace/Gameplay/SwitchablePlayeForLua.prefab",
        --"Arts/Prefab_human/103008_human.prefab"
    })

    -- -3- 
    while not RoleControllerLoader.IsAllLoadingFinish() do 
        coroutine.yield(Yielders.EndOfFrame)
    end 

    -- -4- 
    cs_coroutine.yield_return( RoleControllerLoader.AssembleRole({
        switchablePlayerPrefabPath  = "DreamSpace/Gameplay/SwitchablePlayeForLua.prefab",
        --humanPrefabPath             = "Arts/Prefab_human/103008_human.prefab",
        ---
        initPos = Vector3( 0,1,0 ),
        initRoleDir = Vector3( 0, 0, 1 ).normalized,
        initLookDir = Vector3( 0, 0, 1 ).normalized,
        initHumanScale = Vector3( 0.9, 0.9, 0.9 ), 
        humanCapsuleRadius = 0.3,
        isCat = true, 
        isUseManualViwRotateInPCMode = true,
        isIgnoreJumpHint = false,
        isIgnoreHuman180TurnBack = true,
        isUsePiecesCollector = true,
    }))

    -- -5-
    RoleControllerLoader.ClearLoaders() 

    -- ============

end



function SingleLuaSceneManagerLorLvl2:OnDestroy()

    if self.EventStart then
        Events.RemoveListener(DreamSpaceStates.EventNames.OnCreatePlayerInitEnd, self.EventStart)
        self.EventStart = nil
    end

    if self.EventDestroy then
        Events.RemoveListener(DreamSpaceStates.EventNames.OnCreatePlayerDestroy, self.EventDestroy)
        self.EventDestroy = nil
    end


    Physics.IgnoreLayerCollision( roleLayer, defaultLayer, self.isLayerIgnore_Role_Default ) -- 恢复旧设置
    print( "两层是否碰撞: role-default = " .. tostring(not Physics.GetIgnoreLayerCollision( roleLayer, defaultLayer )) )


    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end



-- ===============================================================


function SingleLuaSceneManagerLorLvl2:Test()
end



function SingleLuaSceneManagerLorLvl2:RegisterInputFunc()
    local KeyboardInputMap = KeyboardInputMap:GetInstance()

    KeyboardInputMap:RegisterInput(KeyboardInfo.InteractiveKey, GearHint.TriggerGearInPCMode)
    KeyboardInputMap:RegisterInput(KeyboardInfo.InspectKey, InspectHint.TriggerInspectInPCMode)

    local playerInputSwitcher = GlobalsInDreamSpace.FindComponent("playerInputSwitcher")
    local CursorLockMode = CS.UnityEngine.CursorLockMode
    local Cursor = CS.UnityEngine.Cursor
    if playerInputSwitcher then
        KeyboardInputMap:RegisterInput(KeyboardInfo.JumpKey, function ()
            print("jump")
            playerInputSwitcher.Env:OnJump()
            --Cursor.lockState = CursorLockMode.Locked
        end)

        KeyboardInputMap:RegisterInput(KeyboardInfo.SwitchKey, function ()
            print("switch")
            playerInputSwitcher.Env:OnSwitch()
        end)

        KeyboardInputMap:RegisterInput(KeyboardInfo.AttackKey, function ()
            print("attack")
            playerInputSwitcher.Env:OnAttack()
        end)

        KeyboardInputMap:RegisterInput(KeyboardInfo.Meow, function()
            print("meow")
            playerInputSwitcher.Env:OnMeow()
        end)
    end
    
end

function SingleLuaSceneManagerLorLvl2:UnRegisterInputFunc()
    local KeyboardInputMap = KeyboardInputMap:GetInstance()
    KeyboardInputMap:UnRegisterInput(KeyboardInfo.InteractiveKey)
    KeyboardInputMap:UnRegisterInput(KeyboardInfo.InspectKey)
    ---
    KeyboardInputMap:UnRegisterInput(KeyboardInfo.SwitchKey)
    KeyboardInputMap:UnRegisterInput(KeyboardInfo.AttackKey)
    KeyboardInputMap:UnRegisterInput(KeyboardInfo.JumpKey)
end




return SingleLuaSceneManagerLorLvl2
